package com.nextgen.gameaggregator.vendor.bng.constant;

import java.util.HashMap;
import java.util.Map;

public class ResponseCodes {
    public static final String INVALID_TOKEN = "INVALID_TOKEN";
    public static final String EXPIRED_TOKEN = "EXPIRED_TOKEN";
    public static final String GAME_NOT_ALLOWED = "GAME_NOT_ALLOWED";
    public static final String TIME_EXCEED = "TIME_EXCEED";
    public static final String LOSS_EXCEED = "LOSS_EXCEED";
    public static final String BET_EXCEED = "BET_EXCEED";
    public static final String FUNDS_EXCEED = "FUNDS_EXCEED";
    public static final String OTHER_EXCEED = "OTHER_EXCEED";
    public static final String SESSION_CLOSED_TRANSACTION = "SESSION_CLOSED";
    public static final String PLAYER_DISCONNECTED = "PLAYER_DISCONNECTED";
    public static final String GAME_REOPENED = "GAME_REOPENED";
    public static final String SESSION_CLOSED_LOGOUT = "SESSION_CLOSED";

    public static final String SUCCESS = "0";

    public static final Map<String, String> RESPONSE_DESCRIPTION = new HashMap<>() {{
        put(INVALID_TOKEN, "Passed token was not generated by the Operator.");
        put(EXPIRED_TOKEN, "The token is expired.");
        put(GAME_NOT_ALLOWED, "The player is not allowed to play this game.");

        put(TIME_EXCEED, "Time limit for a given game is exceeded. This error code may be passed only in case bet != null.");
        put(LOSS_EXCEED, "Loss limit exceeded. This error code may be passed only in case bet != null.");
        put(BET_EXCEED, "Bet limit exceeded. This error code may be passed only in case bet != null.");
        put(FUNDS_EXCEED, "Insufficient funds. This error code may be passed only in case bet != null.");
        put(OTHER_EXCEED, "Another reason. This error code may be passed only in case bet != null.");
        put(SESSION_CLOSED_TRANSACTION, "This error code may be used by the Operator in case you need to kick a player from the game for any reason you have (e.g. expired token, maintenance period, etc). Receiving this error code will cause session close from Booongo’s side. Booongo’s game server won’t accept player’s bet and in a while logout request will be sent to the Operator with SESSION_CLOSED disconnect reason. This error code may be passed only in case transaction’s bet != null.");

        put(PLAYER_DISCONNECTED, "A player disconnected.");
        put(GAME_REOPENED, "A game with a same currency is opened in a new window tab.");
        put(SESSION_CLOSED_LOGOUT, "A player was disconnected after receiving SESSION_CLOSED error code from the Operator.");

        put(SUCCESS, "Success");
    }};
}
